#include <stm32f103x6.h>
#include <stdbool.h>

void led_state(bool state){
	GPIOA->ODR &= ~(1<<1);
	if(state == 1){
		GPIOA->ODR |=  (1<<1);
	}else{
		GPIOA->ODR &= ~(1<<1);
	}
}

int main(void){

RCC->APB2ENR |= (1 << 2); //clock enable for portA
GPIOA->CRL &= ~(0xF << 0);//reset 0
GPIOA->CRL &= ~(0xF << 4); //reset 1
GPIOA->CRL |= (0b1000 << 0);//push-pull input, 0
GPIOA->ODR |= (0b1 <<0); //explicit pull-up(Active low) for pin 0
GPIOA->CRL |= (0b0010 << 4); //push-pull output 2Mhz max speed, 1
bool led;

while(1){
	if((GPIOA->IDR & (1<<0)) == 0){
		led = 1;
		led_state(led);
	}else{
		led = 0;
		led_state(led);
	}
}


}
